/* Ländernamen liefert der Browser, das spart eine eigene Tabelle */
var landName = (function () {
  try {
    var dn = new Intl.DisplayNames(['de'], { type: 'region' });
    return function (cc) { try { return dn.of(cc) || cc; } catch (e) { return cc; } };
  } catch (e) { return function (cc) { return cc; }; }
})();

function schluessel(s) {
  return s.toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

var NACH_ANZEIGE = {};
var ORTE = ROH.split('\n').map(function (z) {
  var f = z.split('|'), zusatz = ZUSAETZE[+f[5]], teile = [];
  if (zusatz) teile.push(zusatz);
  if (!DACH[f[4]]) teile.push(landName(f[4]));
  var o = {
    name: f[0],
    anzeige: f[0] + (teile.length ? ' (' + teile.join(', ') + ')' : ''),
    lat: +f[1], lon: +f[2], tz: ZONEN[+f[3]], land: f[4]
  };
  o.schl = schluessel(o.name);
  NACH_ANZEIGE[o.anzeige.toLowerCase()] = o;
  return o;
});

/* Treffer zu einer Eingabe: Wortanfang vor Enthalten, größte Orte zuerst.
   ORTE ist nach Einwohnerzahl absteigend vorsortiert. */
function suche(eingabe, hoechstens) {
  var q = schluessel(String(eingabe).trim());
  if (!q) return [];
  hoechstens = hoechstens || 30;
  var anfang = [], drin = [];
  for (var i = 0; i < ORTE.length && anfang.length < hoechstens; i++) {
    var p = ORTE[i].schl.indexOf(q);
    if (p === 0) anfang.push(ORTE[i]);
    else if (p > 0 && drin.length < hoechstens) drin.push(ORTE[i]);
  }
  return anfang.concat(drin).slice(0, hoechstens);
}

function finde(anzeige) { return NACH_ANZEIGE[String(anzeige).trim().toLowerCase()] || null; }

function zonenVersatz(tz, y, mo, d, h, mi) {
  function versatzBei(utcMs) {
    var f = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, hour12: false, era: 'short',
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    var p = {}, teile = f.formatToParts(new Date(utcMs));
    teile.forEach(function (t) { p[t.type] = t.value; });
    var jahr = parseInt(p.year, 10);
    if (p.era && /^B/.test(p.era)) jahr = 1 - jahr;
    var alsUtc = Date.UTC(jahr, p.month - 1, +p.day, p.hour % 24, +p.minute, +p.second);
    if (jahr >= 0 && jahr < 100) alsUtc = verschiebeJahr(alsUtc, jahr);
    return (alsUtc - utcMs) / 3600000;
  }
  function verschiebeJahr(ms, jahr) { var dt = new Date(ms); dt.setUTCFullYear(jahr); return dt.getTime(); }
  var roh = Date.UTC(y, mo - 1, d, h, mi, 0);
  if (y >= 0 && y < 100) roh = verschiebeJahr(roh, y);
  var v = versatzBei(roh);
  return versatzBei(roh - v * 3600000);
}

var api = { ORTE: ORTE, suche: suche, finde: finde, zonenVersatz: zonenVersatz, anzahl: ORTE.length };
if (typeof module !== 'undefined' && module.exports) module.exports = api;
root.Orte = api;
